sampler sampler_wrenches;
shader_body
{
uv-=q13*.5;
uv *=2 ;
vec2 m = floor(fract(uv*0.5) * 2.0);
uv = fract(uv)*(1.0 - m) + (m)*fract(1.0 - uv);
uv+=q12*.3;
uv.x=1.0 - uv.x;
uv.y=1.0 - uv.y;
vec2 d = (vec2(1.0)/uTexSize) * 6.0;
